svg.script:
const parts=["part-00.b64","part-01.b64","part-02.b64","part-03.b64","part-04.b64","part-05a.b64","part-05b.b64","part-05c.b64","part-06.b64"];
Promise.all(parts.map(p=>fetch(p,{cache:'no-store'}).then(r=>{if(!r.ok)throw Error(p);return r.text()}))).then(async xs=>{
  const raw=atob(xs.join(''));
  const bytes=Uint8Array.from(raw,c=>c.charCodeAt(0));
  const stream=new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'));
  const html=await new Response(stream).text();
  const frame=document.getElementById('app');
  frame.srcdoc=html;
  frame.onload=()=>{document.getElementById('loading').style.display='none';frame.style.display='block'};
}).catch(e=>document.getElementById('loading').textContent='Preview failed to load: '+e);
